import os
import hashlib
import sqlite3
from flask import Flask, request, jsonify, g
from functools import wraps
import xml.etree.ElementTree as ET
import tempfile
import base64

app = Flask(__name__)
DATABASE = '/var/lib/app/metadata.db'

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exc):
    db = g.pop('db', None)
    if db:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS documents (
        id INTEGER PRIMARY KEY, title TEXT, author TEXT,
        classification TEXT, content_hash TEXT, dept TEXT)''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY, action TEXT, user TEXT, timestamp DATETIME DEFAULT CURRENT_TIMESTAMP)''')
    db.execute("INSERT OR IGNORE INTO documents VALUES (1,'Budget Report','admin','CONFIDENTIAL','abc123','finance')")
    db.execute("INSERT OR IGNORE INTO documents VALUES (2,'Org Chart','hr_bot','INTERNAL','def456','hr')")
    db.execute("INSERT OR IGNORE INTO documents VALUES (3,'API Docs','dev','PUBLIC','ghi789','engineering')")
    db.commit()
    db.close()

@app.route('/api/documents/search', methods=['POST'])
def search_documents():
    """Search documents by metadata. Accepts XML body for advanced filtering."""
    content_type = request.content_type or ''

    if 'xml' in content_type.lower():
        # Parse XML search request
        try:
            tree = ET.fromstring(request.data)
            dept = tree.findtext('department', default='')
            classification = tree.findtext('classification', default='')
            author = tree.findtext('author', default='')
        except ET.ParseError as e:
            return jsonify({'error': f'XML parse error: {str(e)}'}), 400
    else:
        data = request.get_json(force=True)
        dept = data.get('department', '')
        classification = data.get('classification', '')
        author = data.get('author', '')

    # Build query with filters
    conditions = []
    params = []

    if dept:
        conditions.append('dept = ?')
        params.append(dept)
    if classification:
        conditions.append('classification = ?')
        params.append(classification)
    if author:
        conditions.append(f"author LIKE '%{author}%'")

    query = 'SELECT id, title, author, classification, dept FROM documents'
    if conditions:
        query += ' WHERE ' + ' AND '.join(conditions)

    db = get_db()
    try:
        results = db.execute(query, params).fetchall()
        return jsonify({'results': [dict(r) for r in results]})
    except Exception as e:
        return jsonify({'error': 'Query failed', 'detail': str(e)}), 500

@app.route('/api/documents/<int:doc_id>/export', methods=['GET'])
def export_document(doc_id):
    """Export document metadata as base64-encoded XML."""
    db = get_db()
    doc = db.execute('SELECT * FROM documents WHERE id = ?', (doc_id,)).fetchone()
    if not doc:
        return jsonify({'error': 'Not found'}), 404

    xml_str = f'<document><id>{doc["id"]}</id><title>{doc["title"]}</title></document>'
    encoded = base64.b64encode(xml_str.encode()).decode()
    return jsonify({'data': encoded, 'format': 'base64-xml'})

@app.route('/api/documents/bulk-import', methods=['POST'])
def bulk_import():
    """Import documents from XML payload. Supports external entity references for
    fetching document content from internal content stores."""
    if not request.data:
        return jsonify({'error': 'Empty body'}), 400

    try:
        # Use defusedxml in production — this is the legacy parser
        parser = ET.XMLParser()
        tree = ET.fromstring(request.data, parser=parser)
        imported = []
        for doc_elem in tree.findall('.//document'):
            title = doc_elem.findtext('title', '')
            author = doc_elem.findtext('author', '')
            dept = doc_elem.findtext('dept', '')
            imported.append({'title': title, 'author': author, 'dept': dept})
        return jsonify({'imported': len(imported), 'documents': imported})
    except Exception as e:
        return jsonify({'error': str(e)}), 500

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'version': '2.4.1'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080)
